import { existsSync, readFileSync } from "node:fs";
import { resolve } from "node:path";
import { fileURLToPath } from "node:url";

// The catalog is regenerated by hand from class-search exports, so a bad run
// produces plausible-looking JSON rather than an error. This is the gate that
// makes that loud, in the same spirit as ocr:verify --require-ready.
//
// Two real parser bugs motivated it: indented rows shifted every column by one
// and yielded zero matches, and closing a title at the instructor name aborted
// the scan for the course code, silently reducing a 100-class file to one
// record. Both produced a file that parsed fine.

const WEEKDAY_RANGE = [0, 6];
const CLOCK = /^([01]\d|2[0-3]):[0-5]\d$/;

export function verifyCatalogs({ catalogs, institutionIds }) {
  const problems = [];
  const seenInstitutions = new Set();

  for (const [index, catalog] of catalogs.entries()) {
    const where = catalog.institutionId || `entry ${index}`;
    if (!catalog.institutionId) {
      problems.push(`${where}: institutionId is required`);
      continue;
    }
    if (seenInstitutions.has(catalog.institutionId)) {
      problems.push(`${where}: duplicate catalog for the same institution`);
    }
    seenInstitutions.add(catalog.institutionId);
    // A catalog keyed to a school the directory does not contain can never be
    // reached by search, so it is a silent no-op rather than a feature.
    if (institutionIds && !institutionIds.has(catalog.institutionId)) {
      problems.push(`${where}: no institution with this id exists in the directory`);
    }

    const courses = catalog.courses ?? [];
    if (courses.length === 0) continue;

    if (!catalog.sourceLabel?.trim() || !catalog.sourceUrl?.trim()) {
      problems.push(`${where}: ships ${courses.length} courses without sourceLabel and sourceUrl`);
    }
    // Sections are term-specific. Without a term nothing can warn a student that
    // they are looking at last semester's meeting times.
    if (!catalog.termId?.trim() && courses.some((course) => course.sections?.length)) {
      problems.push(`${where}: ships sections without a termId`);
    }

    const seenCodes = new Set();
    for (const course of courses) {
      const code = course.code?.trim();
      if (!code) {
        problems.push(`${where}: a course has no code`);
        continue;
      }
      if (!course.title?.trim()) {
        problems.push(`${where}/${code}: has no title`);
      }
      if (seenCodes.has(code)) {
        problems.push(`${where}/${code}: appears twice; sections should be folded into one course`);
      }
      seenCodes.add(code);

      const seenLines = new Set();
      for (const section of course.sections ?? []) {
        const at = `${where}/${code}/${section.lineNumber || "?"}`;
        if (section.lineNumber && seenLines.has(section.lineNumber)) {
          problems.push(`${at}: duplicate section number`);
        }
        seenLines.add(section.lineNumber);
        for (const day of section.weekdays ?? []) {
          if (!Number.isInteger(day) || day < WEEKDAY_RANGE[0] || day > WEEKDAY_RANGE[1]) {
            problems.push(`${at}: weekday ${day} is outside 0-6`);
          }
        }
        // A meeting with days but no clock, or a clock that runs backwards, is
        // the shape a column-shift bug produces.
        const hasClock = section.startsAtLocal || section.endsAtLocal;
        if (section.weekdays?.length && !hasClock) {
          problems.push(`${at}: has weekdays but no start or end time`);
        }
        for (const [field, value] of [["startsAtLocal", section.startsAtLocal], ["endsAtLocal", section.endsAtLocal]]) {
          if (value && !CLOCK.test(value)) problems.push(`${at}: ${field} "${value}" is not 24-hour HH:MM`);
        }
        if (CLOCK.test(section.startsAtLocal ?? "") && CLOCK.test(section.endsAtLocal ?? "") && section.endsAtLocal <= section.startsAtLocal) {
          problems.push(`${at}: ends at or before it starts`);
        }
      }
    }
  }

  const courses = catalogs.reduce((total, catalog) => total + (catalog.courses?.length ?? 0), 0);
  const sections = catalogs.reduce(
    (total, catalog) => total + (catalog.courses ?? []).reduce((sum, course) => sum + (course.sections?.length ?? 0), 0),
    0,
  );
  return { catalogs: catalogs.length, courses, sections, ready: problems.length === 0, problems };
}

function option(name) {
  return process.argv.find((argument) => argument.startsWith(`${name}=`))?.slice(name.length + 1);
}

const isMain = process.argv[1] && resolve(process.argv[1]) === fileURLToPath(import.meta.url);
if (isMain) {
  const path = resolve(option("--catalogs") ?? "apps/desktop/src-tauri/resources/institution-catalogs.json");
  const directoryPath = resolve(option("--directory") ?? "apps/desktop/src-tauri/resources/institutions-us.json");
  const catalogs = JSON.parse(readFileSync(path, "utf8"));
  const institutionIds = existsSync(directoryPath)
    ? new Set(JSON.parse(readFileSync(directoryPath, "utf8")).map((entry) => entry.id))
    : undefined;
  const result = verifyCatalogs({ catalogs, institutionIds });
  console.log(JSON.stringify(result, null, 2));
  if (!result.ready) {
    console.error(`Course catalog gate failed: ${result.problems.length} problem(s).`);
    process.exitCode = 1;
  }
}
